questionvariables.text:
/* Part (a) */
/* Define a function to generate random numbers with a specified number of decimal places */
decimalplaces(num, places) := float(round(num * 10^places) / 10^places);

/* Function to randomize base_x and ensure a 50/50 split for >1 and <1 */
random_base_x() := block(
    if rand(2) = 0 then
        /* Generate base_x < 1 */
        decimalplaces(0.1 + rand(0.9), 2)
    else
        /* Generate base_x > 1 */
        decimalplaces(1.01 + rand(0.99), 2)
);

/* Function to randomize base_t and ensure a 50/50 split for >1 and <1 */
random_base_t() := block(
    if rand(2) = 0 then
        /* Generate base_t < 1 */
        decimalplaces(0.1 + rand(0.9), 2)
    else
        /* Generate base_t > 1 */
        decimalplaces(1.01 + rand(0.99), 2)
);

/* Generate random base_x and base_t */
base_x: random_base_x();
base_t: random_base_t();
/* Define the functions */
initial_x: rand_with_step(50,300,5);
initial_t: rand_with_prohib(50,300,[initial_x]);
/*base_x:decimalplaces(rand(1.06)+0.1,2);
base_t:decimalplaces(rand(0.97)+0.8,2);*/
fx : initial_x * (base_x)^x;
ft: initial_t * (base_t)^t;
is_growth: if base_x > 1 then  sconcat("\\( \\text{Exponential growth, the growth rate is}, \\, ",base_x," \\, \\text{is greater than} \\, ",1,"\\)")
elseif base_x < 1 and base_x > 0 then
sconcat("\\( \\text{Exponential decay, the decay factor is}\\, ",base_x,"  \\, \\text{is between} \\, ",0,"  \\, \\text{and } \\, ",1,"\\)");
/*Destructors*/
base_x1:decimalplaces(base_x+(rand(0.051)+0.01),2);
base_t1:decimalplaces(base_t+(rand(0.061)+0.1),2);
/* correct answer */
corr_ans:[[1, true, is_growth]];
/* wrong answers */
incorr_ans:[
[2, false, sconcat("\\( \\text{Exponential growth, the growth rate is}, \\, ",base_x1," \\, \\text{is greater than} \\, ",1,"\\)")],
[3, false, sconcat("\\( \\text{Exponential decay, the decay factor is}\\, ",base_t1,"  \\, \\text{is between} \\, ",0,"  \\, \\text{and } \\, ",1,"\\)")]];
ta1: random_permutation(append(corr_ans, incorr_ans));
/*Worked Soln*/
ta_index1: sort(makelist(x[1], x, ta1));

/* Part (b) */
is_decay: if base_t > 1 then  sconcat("\\( \\text{Exponential growth, the growth rate is}, \\, ",base_t," \\, \\text{is greater than} \\, ",1,"\\)")
elseif base_t < 1 and base_t > 0 then
sconcat("\\( \\text{Exponential decay, the decay factor is}\\, ",base_t,"  \\, \\text{is between} \\, ",0,"  \\, \\text{and } \\, ",1,"\\)");
/*Destructors*/
base_x2:base_x+0.010;
base_t2:base_t+0.101;
/* correct answer */
corr_anss:[[1, true, is_decay]];
/* wrong answers */
incorr_anss:[
[2, false, sconcat("\\( \\text{Exponential growth, the growth rate is}, \\, ",base_x2," \\, \\text{is greater than} \\, ",1,"\\)")],
[3, false, sconcat("\\( \\text{Exponential decay, the decay factor is}\\, ",base_t2,"  \\, \\text{is between} \\, ",0,"  \\, \\text{and } \\, ",1,"\\)")]];
ta2: random_permutation(append(corr_anss, incorr_anss));
/*Worked Soln*/
ta_index2: sort(makelist(x[1], x, ta2));
